/**
 * TFSC - Taxonomy Archive Derived Relationship Terms
 * Version 4.1 - Match Logic Synced With Combo Base
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Op een taxonomy-term:
 *
 * huidige term
 * → alle ingevulde relationship_* velden op die term
 * → relevante OPEN vacatures
 * → terms uit Elementor Source taxonomy
 * → Elementor Taxonomy Loop
 *
 * Verschillende taxonomies = AND
 * Meerdere terms binnen dezelfde taxonomy = OR / IN
 * kennisgebied = AND
 *
 * relationship_vacature_button_url wordt bewust NIET gebruikt
 * voor de vacaturequery.
 *
 *
 * ELEMENTOR QUERY IDS
 * ============================================================
 *
 * archive_relationship_level_0
 * archive_relationship_level_1
 * archive_relationship_level_2
 *
 * De Elementor Source bepaalt de target taxonomy.
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

function tfsc_taxrel_v4_vacancy_post_type() {

    return defined( 'TFSC_VACANCY_POST_TYPE' )
        ? TFSC_VACANCY_POST_TYPE
        : 'vacature';
}


function tfsc_taxrel_v4_status_taxonomy() {

    return defined( 'TFSC_STATUS_TAXONOMY' )
        ? TFSC_STATUS_TAXONOMY
        : 'vac_status';
}


function tfsc_taxrel_v4_open_status() {

    return defined( 'TFSC_OPEN_STATUS_SLUG' )
        ? TFSC_OPEN_STATUS_SLUG
        : 'open';
}


function tfsc_taxrel_v4_combo_base() {

    return defined( 'TFSC_COMBO_BASE' )
        ? TFSC_COMBO_BASE
        : 'vacatures';
}


/**
 * ============================================================
 * 2. HUIDIGE TAXONOMY TERM
 * ============================================================
 */

function tfsc_taxrel_v4_current_term() {

    static $cached = null;

    if ( null !== $cached ) {
        return $cached;
    }


    $object =
        get_queried_object();


    /**
     * Normaal taxonomy archive / preview iframe.
     */
    if (
        $object instanceof WP_Term &&
        ! empty( $object->term_id ) &&
        ! empty( $object->taxonomy ) &&
        taxonomy_exists( $object->taxonomy )
    ) {

        if ( is_user_logged_in() ) {

            set_transient(
                'tfsc_taxrel_v4_preview_' . get_current_user_id(),
                [
                    'term_id' =>
                        (int) $object->term_id,

                    'taxonomy' =>
                        $object->taxonomy,
                ],
                5 * MINUTE_IN_SECONDS
            );
        }


        return $cached =
            $object;
    }


    /**
     * Elementor admin-render.
     */
    if (
        is_admin() &&
        $object instanceof WP_Post &&
        is_user_logged_in()
    ) {

        $preview =
            get_transient(
                'tfsc_taxrel_v4_preview_' . get_current_user_id()
            );


        if (
            ! is_array( $preview ) ||
            empty( $preview['term_id'] ) ||
            empty( $preview['taxonomy'] ) ||
            ! taxonomy_exists(
                $preview['taxonomy']
            )
        ) {
            return $cached = false;
        }


        $settings =
            get_post_meta(
                $object->ID,
                '_elementor_page_settings',
                true
            );


        $preview_type =
            is_array( $settings )
                ? ( $settings['preview_type'] ?? '' )
                : '';


        if (
            $preview_type !==
            'taxonomy/' . $preview['taxonomy']
        ) {
            return $cached = false;
        }


        $term =
            get_term(
                (int) $preview['term_id'],
                $preview['taxonomy']
            );


        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {
            return $cached = $term;
        }
    }


    return $cached = false;
}


/**
 * ============================================================
 * 3. HUIDIGE TERM POD
 * ============================================================
 */

function tfsc_taxrel_v4_current_pod() {

    static $resolved = false;
    static $pod      = false;


    if ( $resolved ) {
        return $pod;
    }


    $resolved = true;


    if (
        ! function_exists( 'pods' )
    ) {
        return false;
    }


    $term =
        tfsc_taxrel_v4_current_term();


    if ( ! $term ) {
        return false;
    }


    $pod =
        pods(
            $term->taxonomy,
            (int) $term->term_id
        );


    if (
        ! $pod ||
        ! $pod->exists()
    ) {
        $pod = false;
    }


    return $pod;
}


/**
 * ============================================================
 * 4. RELATIONSHIP DATA NORMALISEREN
 * ============================================================
 */

function tfsc_taxrel_v4_normalize_relationship(
    $value,
    $fallback_taxonomy = ''
) {

    $groups = [];


    if ( empty( $value ) ) {
        return [];
    }


    if (
        is_numeric( $value ) ||
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['pod_item_id'] ) ||
                isset( $value['id'] ) ||
                isset( $value['ID'] )
            )
        )
    ) {
        $value = [ $value ];
    }


    foreach (
        (array) $value
        as $relation
    ) {

        $term_id  = 0;
        $taxonomy = '';


        if ( is_array( $relation ) ) {

            $term_id =
                (int) (
                    $relation['term_id']
                    ?? $relation['pod_item_id']
                    ?? $relation['id']
                    ?? $relation['ID']
                    ?? 0
                );


            $taxonomy =
                sanitize_key(
                    $relation['taxonomy']
                    ?? ''
                );

        } elseif ( is_object( $relation ) ) {

            $term_id =
                (int) (
                    $relation->term_id
                    ?? $relation->pod_item_id
                    ?? $relation->id
                    ?? $relation->ID
                    ?? 0
                );


            $taxonomy =
                sanitize_key(
                    $relation->taxonomy
                    ?? ''
                );

        } elseif ( is_numeric( $relation ) ) {

            $term_id =
                (int) $relation;
        }


        if ( ! $taxonomy ) {

            $taxonomy =
                sanitize_key(
                    $fallback_taxonomy
                );
        }


        if (
            ! $term_id ||
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }


        $term =
            get_term(
                $term_id,
                $taxonomy
            );


        if (
            ! $term instanceof WP_Term ||
            is_wp_error( $term )
        ) {
            continue;
        }


        $groups[
            $taxonomy
        ][] =
            (int) $term_id;
    }


    foreach (
        $groups
        as $taxonomy => $ids
    ) {

        $groups[
            $taxonomy
        ] =
            array_values(
                array_unique(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            );
    }


    return array_filter(
        $groups
    );
}


/**
 * ============================================================
 * 5. ALLE ACTIEVE RELATIONSHIPS OP DE TERM
 * ============================================================
 */

function tfsc_taxrel_v4_relationship_groups() {

    static $cache = null;


    if ( null !== $cache ) {
        return $cache;
    }


    $cache = [];


    $pod =
        tfsc_taxrel_v4_current_pod();


    if ( ! $pod ) {
        return [];
    }


    $fields =
        $pod->fields();


    if (
        ! is_array( $fields )
    ) {
        return [];
    }


    foreach (
        $fields
        as $field_name => $field_data
    ) {

        if (
            0 !== strpos(
                $field_name,
                'relationship_'
            ) ||
            'relationship_vacature_button_url'
            === $field_name
        ) {
            continue;
        }


        $value =
            $pod->field(
                $field_name
            );


        if (
            empty( $value )
        ) {
            continue;
        }


        $fallback_taxonomy =
            sanitize_key(
                substr(
                    $field_name,
                    strlen(
                        'relationship_'
                    )
                )
            );


        $groups =
            tfsc_taxrel_v4_normalize_relationship(
                $value,
                $fallback_taxonomy
            );


        foreach (
            $groups
            as $taxonomy => $ids
        ) {

            $cache[
                $taxonomy
            ] =
                array_merge(
                    $cache[
                        $taxonomy
                    ]
                    ?? [],
                    $ids
                );
        }
    }


    foreach (
        $cache
        as $taxonomy => $ids
    ) {

        $cache[
            $taxonomy
        ] =
            array_values(
                array_unique(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            );
    }


    return array_filter(
        $cache
    );
}


/**
 * ============================================================
 * 6. OPEN VACATURES
 * ============================================================
 *
 * Zelfde match-logica als de combo Base:
 *
 * verschillende taxonomies = AND
 *
 * binnen taxonomy:
 * - kennisgebied = AND
 * - overige = IN / OR
 */

function tfsc_taxrel_v4_vacancy_ids(
    $groups
) {

    static $cache = [];


    if (
        empty( $groups )
    ) {
        return [];
    }


    $cache_key =
        md5(
            serialize(
                $groups
            )
        );


    if (
        isset(
            $cache[
                $cache_key
            ]
        )
    ) {
        return $cache[
            $cache_key
        ];
    }


    $tax_query = [
        'relation' =>
            'AND',
    ];


    foreach (
        $groups
        as $taxonomy => $ids
    ) {

        if (
            ! taxonomy_exists( $taxonomy ) ||
            ! $ids
        ) {
            continue;
        }


        $ids =
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $ids
                        )
                    )
                )
            );


        if ( ! $ids ) {
            continue;
        }


        /**
         * Zelfde centrale match-logica als Base.
         */
        $method =
            function_exists(
                'tfsc_get_combo_taxonomy_match_method'
            )
                ? tfsc_get_combo_taxonomy_match_method(
                    $taxonomy
                )
                : (
                    'kennisgebied' === $taxonomy
                        ? 'AND'
                        : 'OR'
                );


        $tax_query[] = [
            'taxonomy' =>
                $taxonomy,

            'field' =>
                'term_id',

            'terms' =>
                $ids,

            'operator' =>
                (
                    'AND' === $method &&
                    count( $ids ) > 1
                )
                    ? 'AND'
                    : 'IN',

            'include_children' =>
                false,
        ];
    }


    if (
        count( $tax_query ) <= 1
    ) {
        return [];
    }


    $status_taxonomy =
        tfsc_taxrel_v4_status_taxonomy();


    if (
        taxonomy_exists(
            $status_taxonomy
        )
    ) {

        $tax_query[] = [
            'taxonomy' =>
                $status_taxonomy,

            'field' =>
                'slug',

            'terms' => [
                tfsc_taxrel_v4_open_status(),
            ],

            'operator' =>
                'IN',

            'include_children' =>
                false,
        ];
    }


    $ids =
        get_posts(
            [
                'post_type' =>
                    tfsc_taxrel_v4_vacancy_post_type(),

                'post_status' =>
                    'publish',

                'posts_per_page' =>
                    -1,

                'fields' =>
                    'ids',

                'no_found_rows' =>
                    true,

                'tax_query' =>
                    $tax_query,
            ]
        );


    return $cache[
        $cache_key
    ] =
        array_values(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            )
        );
}


/**
 * ============================================================
 * 7. TARGET TERMS
 * ============================================================
 */

function tfsc_taxrel_v4_target_terms(
    $vacancy_ids,
    $taxonomy
) {

    if (
        ! $vacancy_ids ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return [];
    }


    $ids =
        wp_get_object_terms(
            array_map(
                'intval',
                $vacancy_ids
            ),
            $taxonomy,
            [
                'fields' =>
                    'ids',
            ]
        );


    if (
        is_wp_error( $ids ) ||
        ! $ids
    ) {
        return [];
    }


    $ids =
        array_map(
            'intval',
            $ids
        );


    if (
        is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {

        foreach (
            $ids
            as $term_id
        ) {

            $ids =
                array_merge(
                    $ids,
                    get_ancestors(
                        $term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                );
        }
    }


    return array_values(
        array_unique(
            array_map(
                'intval',
                $ids
            )
        )
    );
}


/**
 * ============================================================
 * 8. EXACT LEVEL
 * ============================================================
 */

function tfsc_taxrel_v4_filter_level(
    $ids,
    $taxonomy,
    $level
) {

    if ( ! $ids ) {
        return [];
    }


    if (
        ! is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {

        return (
            0 === (int) $level
        )
            ? array_values(
                array_unique(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            )
            : [];
    }


    return array_values(
        array_filter(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            ),
            function(
                $term_id
            ) use (
                $taxonomy,
                $level
            ) {

                return (
                    count(
                        get_ancestors(
                            $term_id,
                            $taxonomy,
                            'taxonomy'
                        )
                    )
                    ===
                    (int) $level
                );
            }
        )
    );
}


/**
 * ============================================================
 * 9. QUERY ID
 * ============================================================
 */

function tfsc_taxrel_v4_parse_query_id(
    $query_id
) {

    if (
        ! preg_match(
            '/^archive_relationship_level_([0-9]+)$/',
            (string) $query_id,
            $matches
        )
    ) {
        return false;
    }


    return (int)
        $matches[1];
}


/**
 * ============================================================
 * 10. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        $query_id =
            $settings[
                'term_taxonomy_id'
            ]
            ??
            $settings[
                'post_taxonomy_term_taxonomy_id'
            ]
            ??
            '';


        $level =
            tfsc_taxrel_v4_parse_query_id(
                $query_id
            );


        if (
            false === $level ||
            ! tfsc_taxrel_v4_current_term()
        ) {
            return $args;
        }


        $taxonomy =
            $args['taxonomy']
            ??
            $settings[
                'post_taxonomy_query_post_type'
            ]
            ??
            '';


        if (
            is_array( $taxonomy )
        ) {
            $taxonomy =
                reset(
                    $taxonomy
                );
        }


        $taxonomy =
            sanitize_key(
                $taxonomy
            );


        if (
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy ) ||
            $taxonomy ===
                tfsc_taxrel_v4_status_taxonomy()
        ) {
            return $args;
        }


        $groups =
            tfsc_taxrel_v4_relationship_groups();


        $vacancy_ids =
            tfsc_taxrel_v4_vacancy_ids(
                $groups
            );


        $target_ids =
            tfsc_taxrel_v4_target_terms(
                $vacancy_ids,
                $taxonomy
            );


        $target_ids =
            tfsc_taxrel_v4_filter_level(
                $target_ids,
                $taxonomy,
                $level
            );


        if (
            ! $target_ids
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        unset(
            $args[
                'term_taxonomy_id'
            ]
        );


        $args['taxonomy'] =
            $taxonomy;

        $args['include'] =
            $target_ids;

        $args['hide_empty'] =
            false;

        $args['hierarchical'] =
            false;


        /**
         * Marker voor sortering.
         */
        $args[
            'tfsc_taxrel_v4'
        ] = 1;


        /**
         * Alleen deze target-taxonomy krijgt combo-links.
         */
        $GLOBALS[
            'tfsc_taxrel_v4_active_targets'
        ][ $taxonomy ] =
            true;


        return $args;
    },
    40,
    3
);


/**
 * ============================================================
 * 11. SORTERING OP NAAM
 * ============================================================
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if (
            empty(
                $args[
                    'tfsc_taxrel_v4'
                ]
            ) ||
            ! is_array( $terms ) ||
            ! $terms
        ) {
            return $terms;
        }


        if (
            isset(
                $args['orderby']
            ) &&
            'name' !==
                strtolower(
                    (string)
                    $args['orderby']
                )
        ) {
            return $terms;
        }


        $order =
            strtoupper(
                (string) (
                    $args['order']
                    ?? 'ASC'
                )
            );


        usort(
            $terms,
            function(
                $a,
                $b
            ) use (
                $order
            ) {

                if (
                    ! $a instanceof WP_Term ||
                    ! $b instanceof WP_Term
                ) {
                    return 0;
                }


                $compare =
                    strnatcasecmp(
                        remove_accents(
                            $a->name
                        ),
                        remove_accents(
                            $b->name
                        )
                    );


                return (
                    'DESC' === $order
                )
                    ? -$compare
                    : $compare;
            }
        );


        return $terms;
    },
    9999,
    4
);


/**
 * ============================================================
 * 12. TERM PATH
 * ============================================================
 */

function tfsc_taxrel_v4_term_path(
    $term
) {

    if (
        ! $term instanceof WP_Term
    ) {
        return '';
    }


    $slugs =
        [];


    if (
        is_taxonomy_hierarchical(
            $term->taxonomy
        )
    ) {

        foreach (
            array_reverse(
                get_ancestors(
                    $term->term_id,
                    $term->taxonomy,
                    'taxonomy'
                )
            )
            as $ancestor_id
        ) {

            $ancestor =
                get_term(
                    $ancestor_id,
                    $term->taxonomy
                );


            if (
                $ancestor instanceof WP_Term &&
                ! is_wp_error(
                    $ancestor
                )
            ) {

                $slugs[] =
                    $ancestor->slug;
            }
        }
    }


    $slugs[] =
        $term->slug;


    return implode(
        '/',
        array_map(
            'rawurlencode',
            $slugs
        )
    );
}


/**
 * ============================================================
 * 13. COMBO URL
 * ============================================================
 *
 * URL-logica voorlopig bewust lokaal behouden.
 *
 * Alle actieve relationships
 * +
 * aangeklikte target term.
 */

function tfsc_taxrel_v4_combo_url(
    $target_term = null
) {

    $groups =
        tfsc_taxrel_v4_relationship_groups();


    if (
        ! $groups
    ) {
        return false;
    }


    $parts = [
        tfsc_taxrel_v4_combo_base(),
    ];


    foreach (
        $groups
        as $taxonomy => $ids
    ) {

        foreach (
            $ids
            as $term_id
        ) {

            /**
             * Exact dezelfde target term
             * niet dubbel opnemen.
             */
            if (
                $target_term instanceof WP_Term &&
                $taxonomy ===
                    $target_term->taxonomy &&
                (int) $term_id ===
                    (int) $target_term->term_id
            ) {
                continue;
            }


            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                ! $term instanceof WP_Term ||
                is_wp_error( $term )
            ) {
                continue;
            }


            $path =
                tfsc_taxrel_v4_term_path(
                    $term
                );


            if (
                '' === $path
            ) {
                continue;
            }


            $parts[] =
                $taxonomy;

            $parts[] =
                $path;
        }
    }


    if (
        $target_term instanceof WP_Term
    ) {

        $target_path =
            tfsc_taxrel_v4_term_path(
                $target_term
            );


        if (
            '' === $target_path
        ) {
            return false;
        }


        $parts[] =
            $target_term->taxonomy;

        $parts[] =
            $target_path;
    }


    return home_url(
        '/'
        .
        implode(
            '/',
            array_map(
                static fn( $part ) =>
                    trim(
                        $part,
                        '/'
                    ),
                $parts
            )
        )
        .
        '/'
    );
}


/**
 * ============================================================
 * 14. TERM LINKS → COMBO URL
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if (
            ! empty(
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ]
            ) ||
            is_admin() ||
            ! $term instanceof WP_Term ||
            ! tfsc_taxrel_v4_current_term()
        ) {
            return $termlink;
        }


        if (
            empty(
                $GLOBALS[
                    'tfsc_taxrel_v4_active_targets'
                ][ $taxonomy ]
            )
        ) {
            return $termlink;
        }


        $url =
            tfsc_taxrel_v4_combo_url(
                $term
            );


        return $url
            ?: $termlink;
    },
    40,
    3
);

/**
 * TFSC - Elementor Posts filteren via Pods taxonomy relationships
 *
 * Query ID:
 * relationship_posts
 *
 * Doel:
 * Filtert een Elementor Posts/Loop Grid automatisch op basis van de
 * Pods relationshipvelden van de huidige post, CPT of taxonomy-term.
 *
 * Belangrijk:
 * - RAW Pods relationshipdata is leidend.
 * - Verschillende taxonomies = AND.
 * - Meerdere terms binnen dezelfde taxonomy = IN / OR.
 * - Elementor Source blijft leidend.
 * - relationship_vacature_button_url wordt bewust genegeerd.
 * - Werkt ook in Elementor Theme Builder preview voor posts/CPT's.
 */


/**
 * ============================================================
 * CONTEXT + POD
 * ============================================================
 *
 * Bepaalt het Pods-object van de huidige context:
 *
 * - taxonomy archive → Pod van de huidige term;
 * - post / CPT → Pod van de huidige post;
 * - Elementor Theme Builder → gebruikt indien beschikbaar
 *   tfsc_derived_rel_v3_get_context_post_id() om de echte
 *   preview-post te vinden.
 */

function tfsc_relposts_v3_get_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $object = get_queried_object();

    /*
     * Taxonomy term.
     */
    if ( $object instanceof WP_Term ) {

        $pod = pods(
            $object->taxonomy,
            (int) $object->term_id
        );

        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }

    /*
     * Post / CPT / Elementor preview.
     */
    $post_id = 0;

    if (
        function_exists(
            'tfsc_derived_rel_v3_get_context_post_id'
        )
    ) {
        $post_id =
            (int)
            tfsc_derived_rel_v3_get_context_post_id();

    } elseif (
        function_exists(
            'tfsc_derived_rel_v2_get_context_post_id'
        )
    ) {
        $post_id =
            (int)
            tfsc_derived_rel_v2_get_context_post_id();
    }

    if (
        ! $post_id &&
        $object instanceof WP_Post &&
        'elementor_library'
        !==
        get_post_type( $object->ID )
    ) {
        $post_id =
            (int) $object->ID;
    }

    if ( ! $post_id ) {
        return false;
    }

    $post_type =
        get_post_type(
            $post_id
        );

    if ( ! $post_type ) {
        return false;
    }

    $pod = pods(
        $post_type,
        $post_id
    );

    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}


/**
 * ============================================================
 * RAW RELATIONSHIP NORMALISEREN
 * ============================================================
 *
 * Pods kan relationshipdata als array of object teruggeven.
 * Deze functie maakt daar steeds dit formaat van:
 *
 * [
 *     [
 *         'taxonomy' => 'functie-inhoud',
 *         'term_id'  => 220,
 *     ],
 * ]
 *
 * De taxonomy wordt dus NIET afgeleid uit de fieldnaam.
 * De daadwerkelijke RAW relationshipdata bepaalt welke taxonomy
 * en term gebruikt worden.
 */

function tfsc_relposts_v3_normalize_relationship(
    $value
) {

    if ( empty( $value ) ) {
        return [];
    }

    /*
     * Eén relationship normaliseren naar een lijst.
     */
    if (
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['taxonomy'] )
            )
        )
    ) {
        $value = [ $value ];
    }

    if ( ! is_array( $value ) ) {
        return [];
    }

    $result = [];

    foreach ( $value as $relation ) {

        if ( is_array( $relation ) ) {

            $taxonomy =
                sanitize_key(
                    $relation['taxonomy']
                    ?? ''
                );

            $term_id = (int) (
                $relation['term_id']
                ?? $relation['pod_item_id']
                ?? $relation['id']
                ?? $relation['ID']
                ?? 0
            );

        } elseif ( is_object( $relation ) ) {

            $taxonomy =
                sanitize_key(
                    $relation->taxonomy
                    ?? ''
                );

            $term_id = (int) (
                $relation->term_id
                ?? $relation->pod_item_id
                ?? $relation->id
                ?? $relation->ID
                ?? 0
            );

        } else {

            continue;
        }

        /*
         * Alleen echte, bestaande taxonomy-terms accepteren.
         */
        if (
            ! $taxonomy ||
            ! $term_id ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }

        $term =
            get_term(
                $term_id,
                $taxonomy
            );

        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {
            $result[] = [
                'taxonomy' => $taxonomy,
                'term_id'  => $term_id,
            ];
        }
    }

    return $result;
}


/**
 * ============================================================
 * TAXONOMY HOORT BIJ ELEMENTOR SOURCE?
 * ============================================================
 *
 * Een relationship wordt alleen gebruikt als de betreffende
 * taxonomy gekoppeld is aan het post type dat Elementor als
 * Source gebruikt.
 */

function tfsc_relposts_v3_taxonomy_matches_source(
    $taxonomy,
    $post_types
) {

    $object =
        get_taxonomy(
            $taxonomy
        );

    if ( ! $object ) {
        return false;
    }

    return (bool) array_intersect(
        (array) $post_types,
        (array) $object->object_type
    );
}


/**
 * ============================================================
 * ELEMENTOR QUERY
 * ============================================================
 *
 * Query ID in Elementor:
 *
 * relationship_posts
 */

add_action(
    'elementor/query/relationship_posts',
    function( $query ) {

        $pod =
            tfsc_relposts_v3_get_pod();

        if ( ! $pod ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Elementor Source.
         */
        $post_types =
            array_values(
                array_filter(
                    (array) $query->get( 'post_type' )
                )
            );

        if ( ! $post_types ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        $fields =
            $pod->fields();

        if ( ! is_array( $fields ) || ! $fields ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Relationship terms groeperen per taxonomy.
         */
        $groups = [];

        foreach ( $fields as $field_name => $definition ) {

            if (
                ! is_string( $field_name ) ||
                0 !== strpos(
                    $field_name,
                    'relationship_'
                ) ||
                'relationship_vacature_button_url'
                ===
                $field_name
            ) {
                continue;
            }

            /*
             * RAW Pods relationship uitlezen.
             */
            $relationships =
                tfsc_relposts_v3_normalize_relationship(
                    $pod->field(
                        $field_name
                    )
                );

            foreach (
                $relationships
                as $relationship
            ) {

                $taxonomy =
                    $relationship['taxonomy'];

                /*
                 * Alleen gebruiken als taxonomy bij de
                 * Elementor Source hoort.
                 */
                if (
                    ! tfsc_relposts_v3_taxonomy_matches_source(
                        $taxonomy,
                        $post_types
                    )
                ) {
                    continue;
                }

                $groups[ $taxonomy ][] =
                    (int) $relationship['term_id'];
            }
        }

        /*
         * Dubbele en ongeldige IDs verwijderen.
         */
        foreach (
            $groups
            as $taxonomy => $ids
        ) {

            $ids =
                array_values(
                    array_unique(
                        array_filter(
                            array_map(
                                'intval',
                                $ids
                            )
                        )
                    )
                );

            if ( $ids ) {
                $groups[ $taxonomy ] = $ids;
            } else {
                unset( $groups[ $taxonomy ] );
            }
        }

        /*
         * Geen bruikbare relationships:
         * bewust geen posts tonen.
         */
        if ( ! $groups ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Verschillende taxonomies = AND.
         * Meerdere terms binnen taxonomy = IN.
         */
        $relationship_query = [
            'relation' => 'AND',
        ];

        foreach (
            $groups
            as $taxonomy => $ids
        ) {

            $relationship_query[] = [
                'taxonomy'         => $taxonomy,
                'field'            => 'term_id',
                'terms'            => $ids,
                'operator'         => 'IN',
                'include_children' => true,
            ];
        }

        /*
         * Elementor kan al tax_query-voorwaarden bevatten, bijvoorbeeld
         * vac_status = Ingevuld uitsluiten. Die mogen niet worden vervangen.
         * De relationshipvoorwaarden worden daarom als extra AND-groep
         * naast de bestaande Elementor-query geplaatst.
         */
        $existing_tax_query = $query->get( 'tax_query' );

        if (
            is_array( $existing_tax_query ) &&
            ! empty( $existing_tax_query )
        ) {
            $combined_tax_query = [
                'relation' => 'AND',
                $existing_tax_query,
                $relationship_query,
            ];
        } else {
            $combined_tax_query = $relationship_query;
        }

        $query->set(
            'tax_query',
            $combined_tax_query
        );
    },
    20,
    1
);

/**
 * TFSC - Vacature Button URL + Text
 *
 * Shortcodes:
 *
 * [vacature_button_url]
 * [vacature_button_text]
 *
 * ============================================================
 * WERKING
 * ============================================================
 *
 * 1. relationship_vacature_button_url gevuld?
 *
 *    → gebruik native taxonomy-term URL
 *    → buttontekst = naam van die term
 *
 * 2. relationship_vacature_button_url leeg?
 *
 *    CPT / post:
 *    → tfsc_derived_rel_v3_effective_relationship_groups() met fallback
 *
 *    Taxonomy / term:
 *    → tfsc_taxrel_v4_relationship_groups()
 *
 *    → bouw één TFSC combo archive URL
 *    → buttontekst = "Bekijk vacatures"
 */


/**
 * ============================================================
 * 1. HUIDIGE POD
 * ============================================================
 */

function tfsc_vacature_button_v4_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $object = get_queried_object();

    /**
     * Taxonomy-term.
     *
     * Gebruik indien mogelijk dezelfde resolver als
     * de taxonomy relationship-loop.
     */
    if (
        function_exists( 'tfsc_taxrel_v4_current_term' )
    ) {
        $term = tfsc_taxrel_v4_current_term();

        if ( $term instanceof WP_Term ) {

            $pod = pods(
                $term->taxonomy,
                (int) $term->term_id
            );

            return (
                $pod &&
                $pod->exists()
            )
                ? $pod
                : false;
        }
    }

    if ( $object instanceof WP_Term ) {

        $pod = pods(
            $object->taxonomy,
            (int) $object->term_id
        );

        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }

    /**
     * CPT / post / Elementor preview.
     */
    if (
        function_exists(
            'tfsc_derived_rel_v3_get_context_post_id'
        )
    ) {
        $post_id = (int)
            tfsc_derived_rel_v3_get_context_post_id();

    } elseif (
        function_exists(
            'tfsc_derived_rel_v2_get_context_post_id'
        )
    ) {
        $post_id = (int)
            tfsc_derived_rel_v2_get_context_post_id();

    } elseif (
        $object instanceof WP_Post
    ) {
        $post_id = (int) $object->ID;

    } else {
        $post_id =
            (int) get_queried_object_id();
    }

    if ( ! $post_id ) {
        return false;
    }

    $post_type =
        get_post_type(
            $post_id
        );

    if (
        ! $post_type ||
        'elementor_library' === $post_type
    ) {
        return false;
    }

    $pod = pods(
        $post_type,
        $post_id
    );

    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}


/**
 * ============================================================
 * 2. EXPLICIETE BUTTON TERM
 * ============================================================
 *
 * relationship_vacature_button_url
 */

function tfsc_vacature_button_v4_explicit_term() {

    $pod =
        tfsc_vacature_button_v4_pod();

    if ( ! $pod ) {
        return false;
    }

    $value =
        $pod->field(
            'relationship_vacature_button_url'
        );

    if ( empty( $value ) ) {
        return false;
    }

    if (
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['pod_item_id'] ) ||
                isset( $value['id'] ) ||
                isset( $value['ID'] )
            )
        )
    ) {
        $value = [ $value ];
    }

    foreach ( (array) $value as $relation ) {

        $term_id  = 0;
        $taxonomy = '';

        if ( is_array( $relation ) ) {

            $term_id = (int) (
                $relation['term_id']
                ?? $relation['pod_item_id']
                ?? $relation['id']
                ?? $relation['ID']
                ?? 0
            );

            $taxonomy =
                sanitize_key(
                    $relation['taxonomy']
                    ?? ''
                );

        } elseif ( is_object( $relation ) ) {

            $term_id = (int) (
                $relation->term_id
                ?? $relation->pod_item_id
                ?? $relation->id
                ?? $relation->ID
                ?? 0
            );

            $taxonomy =
                sanitize_key(
                    $relation->taxonomy
                    ?? ''
                );
        }

        if (
            ! $term_id ||
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }

        $term =
            get_term(
                $term_id,
                $taxonomy
            );

        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {
            return $term;
        }
    }

    return false;
}


/**
 * ============================================================
 * 3. ACTIEVE RELATIONSHIP GROUPS
 * ============================================================
 *
 * Taxonomy-term:
 * → tfsc_taxrel_v4_relationship_groups()
 *
 * CPT / post:
 * → tfsc_derived_rel_v3_relationship_groups()
 */

function tfsc_vacature_button_v4_relationship_groups() {

    $object =
        get_queried_object();

    /**
     * Taxonomy context.
     */
    if (
        $object instanceof WP_Term ||
        (
            function_exists(
                'tfsc_taxrel_v4_current_term'
            ) &&
            tfsc_taxrel_v4_current_term()
            instanceof WP_Term
        )
    ) {

        return function_exists(
            'tfsc_taxrel_v4_relationship_groups'
        )
            ? tfsc_taxrel_v4_relationship_groups()
            : [];
    }

    /**
     * CPT / post context.
     * Gebruik de gevalideerde fallback-groepen wanneer beschikbaar.
     */
    if ( function_exists(
        'tfsc_derived_rel_v3_effective_relationship_groups'
    ) ) {
        return tfsc_derived_rel_v3_effective_relationship_groups();
    }

    return function_exists(
        'tfsc_derived_rel_v3_relationship_groups'
    )
        ? tfsc_derived_rel_v3_relationship_groups()
        : [];
}


/**
 * ============================================================
 * 4. TERM PATH
 * ============================================================
 */

function tfsc_vacature_button_v4_term_path(
    $term
) {

    if (
        function_exists(
            'tfsc_taxrel_v4_term_path'
        )
    ) {
        return tfsc_taxrel_v4_term_path(
            $term
        );
    }

    if (
        function_exists(
            'tfsc_derived_rel_v3_term_path'
        )
    ) {
        return tfsc_derived_rel_v3_term_path(
            $term
        );
    }

    if ( ! $term instanceof WP_Term ) {
        return '';
    }

    return rawurlencode(
        $term->slug
    );
}


/**
 * ============================================================
 * 5. COMBO BASE
 * ============================================================
 */

function tfsc_vacature_button_v4_combo_base() {

    if ( defined( 'TFSC_COMBO_BASE' ) ) {
        return TFSC_COMBO_BASE;
    }

    return 'vacatures';
}


/**
 * ============================================================
 * 6. COMBO URL
 * ============================================================
 */

function tfsc_vacature_button_v4_combo_url() {

    $groups =
        tfsc_vacature_button_v4_relationship_groups();

    if ( ! $groups ) {
        return '';
    }

    $parts = [
        tfsc_vacature_button_v4_combo_base(),
    ];

    foreach (
        $groups
        as $taxonomy => $term_ids
    ) {

        foreach (
            $term_ids
            as $term_id
        ) {

            $term =
                get_term(
                    (int) $term_id,
                    $taxonomy
                );

            if (
                ! $term instanceof WP_Term ||
                is_wp_error( $term )
            ) {
                continue;
            }

            $path =
                tfsc_vacature_button_v4_term_path(
                    $term
                );

            if ( ! $path ) {
                continue;
            }

            $parts[] =
                $taxonomy;

            $parts[] =
                $path;
        }
    }

    if ( count( $parts ) <= 1 ) {
        return '';
    }

    return home_url(
        '/'
        .
        implode(
            '/',
            array_map(
                static fn( $part ) =>
                    trim( $part, '/' ),
                $parts
            )
        )
        .
        '/'
    );
}


/**
 * ============================================================
 * 7. BUTTON URL
 * ============================================================
 *
 * [vacature_button_url]
 */

add_shortcode(
    'vacature_button_url',
    function() {

        /**
         * Expliciete selectie heeft altijd voorrang.
         */
        $term =
            tfsc_vacature_button_v4_explicit_term();

        if ( $term ) {

            $GLOBALS[
                'tfsc_force_native_term_link'
            ] = true;

            $url =
                get_term_link(
                    $term
                );

            unset(
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ]
            );

            return is_wp_error( $url )
                ? ''
                : esc_url( $url );
        }

        /**
         * Geen expliciete selectie:
         * combo van alle actieve relationships.
         */
        $url =
            tfsc_vacature_button_v4_combo_url();

        return $url
            ? esc_url( $url )
            : esc_url( home_url( '/vacatures/' ) );
    }
);


/**
 * ============================================================
 * 8. BUTTON TEXT
 * ============================================================
 *
 * [vacature_button_text]
 *
 * Expliciete term:
 * → naam van de term
 *
 * Combo:
 * → Bekijk vacatures
 */

add_shortcode(
    'vacature_button_text',
    function() {

        $term =
            tfsc_vacature_button_v4_explicit_term();

        if ( $term ) {
            return esc_html(
                $term->name
            );
        }

        return 'Bekijk vacatures';
    }
);
